from summarize import summarize

def test_summarize_empty():
    assert summarize([]) == {}

def test_summarize_single_valid():
    rows = [{'region': 'North', 'revenue': '100'}]
    assert summarize(rows) == {'North': 100.0}

def test_summarize_multiple_regions():
    rows = [
        {'region': 'North', 'revenue': '100'},
        {'region': 'South', 'revenue': '200'},
        {'region': 'North', 'revenue': '50'},
    ]
    assert summarize(rows) == {'North': 150.0, 'South': 200.0}

def test_summarize_unparseable_revenue():
    rows = [
        {'region': 'East', 'revenue': 'abc'},
        {'region': 'West', 'revenue': None},
        {'region': 'East', 'revenue': '75'},
    ]
    assert summarize(rows) == {'East': 75.0}

